const fs = require("fs");
const path = require("path");
const cp = require("child_process");
const dir = "/w/jsondefault";
fs.rmSync(dir, { recursive: true, force: true });
fs.mkdirSync(dir, { recursive: true });
fs.writeFileSync(path.join(dir, "math.test.mjs"), [
  "import { test, expect } from 'vitest'",
  "test('adds', () => { expect(1 + 1).toBe(2) })",
].join("\n") + "\n");
const r = cp.spawnSync(process.execPath, ["/w/node_modules/vitest/vitest.mjs", "run", "--reporter=json"], {
  cwd: dir,
  encoding: "utf8",
  env: { ...process.env, NO_COLOR: "1", CI: "1" },
  timeout: 60000,
});
const out = (r.stdout || "") + (r.stderr || "") + (r.error ? String(r.error) : "");
console.log(out);
const reportFile = path.join(dir, ".vitest", "json", "output.json");
if (fs.existsSync(reportFile)) {
  let report;
  try { report = JSON.parse(fs.readFileSync(reportFile, "utf8")); } catch (e) {
    console.error("ERROR: .vitest/json/output.json is not valid JSON");
    process.exit(2);
  }
  if (r.status === 0 && report.numPassedTests === 1 && !/"numPassedTests"/.test(r.stdout || "")) {
    console.log("PASS: --reporter=json wrote .vitest/json/output.json by default and kept the report off stdout");
    process.exit(0);
  }
  console.error("ERROR: unexpected report (exit " + r.status + ", passed " + report.numPassedTests + ")");
  process.exit(2);
}
// The symptom of the old behavior: the run passed and the JSON report went to stdout, not to a file.
if (r.status === 0 && /"numPassedTests":1/.test(r.stdout || "")) {
  console.error("FAIL: --reporter=json printed the report to stdout and wrote no .vitest/json/output.json");
  process.exit(1);
}
console.error("ERROR: unexpected result (exit " + r.status + ")");
process.exit(2);

